# ---------------- texto em vetor (fonte Antonio) ----------------
def width(text, w="b", size=20, ls=0):
    f = G[w]; s = size / f["upm"]
    return sum(f["g"].get(c, f["g"][" "])[0] * s + ls for c in text) - (ls if text else 0)

def T(text, x, y, size, w="b", fill=LIGHT, anchor="start", ls=0):
    f = G[w]; s = size / f["upm"]
    if anchor != "start":
        wd = width(text, w, size, ls); x -= wd if anchor == "end" else wd / 2
    parts, cx = [], 0
    for c in text:
        adv, d = f["g"].get(c, f["g"][" "])
        if d: parts.append(f'<path transform="translate({cx:.0f},0)" d="{d}"/>')
        cx += adv + ls / s
    return f'<g fill="{fill}" transform="translate({x:.1f},{y:.1f}) scale({s:.5f},{-s:.5f})">{"".join(parts)}</g>'

def svg(w, h, body, style=""):
    st = f"<style>{style}@media (prefers-reduced-motion:reduce){{*{{animation:none!important}}}}</style>" if style else ""
    return f'<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="{h}" viewBox="0 0 {w} {h}">{st}<rect width="{w}" height="{h}" rx="32" fill="{INK}"/>{body}</svg>'

def head(title, x=36, y=56):
    return f'<circle cx="{x+6}" cy="{y-9}" r="6" fill="{RED}"/>' + T(title, x + 22, y, 22, "r", GREY, ls=2.5)

def save(name, s):
    os.makedirs(OUT, exist_ok=True)
    open(os.path.join(OUT, name), "w", encoding="utf-8").write(s)

# ---------------- dados ----------------
def gql(query, variables):
    req = urllib.request.Request("https://api.github.com/graphql",
        data=json.dumps({"query": query, "variables": variables}).encode(),
        headers={"Authorization": f"bearer {TOKEN}", "Content-Type": "application/json"})
    r = json.load(urllib.request.urlopen(req))
    if "errors" in r: sys.exit(r["errors"])
    return r["data"]

def fetch():
    d = gql("""query($u:String!){user(login:$u){
      createdAt
      pullRequests{totalCount} issues{totalCount}
      repositories(ownerAffiliations:OWNER,isFork:false,first:100){totalCount nodes{stargazerCount
        languages(first:10,orderBy:{field:SIZE,direction:DESC}){edges{size node{name}}}}}
      contributionsCollection{contributionYears totalCommitContributions}}}""", {"u": USER})["user"]
    days = {}
    for y in d["contributionsCollection"]["contributionYears"]:
        c = gql("""query($u:String!,$f:DateTime!,$t:DateTime!){user(login:$u){
          contributionsCollection(from:$f,to:$t){contributionCalendar{weeks{contributionDays{date contributionCount}}}}}}""",
          {"u": USER, "f": f"{y}-01-01T00:00:00Z", "t": f"{y}-12-31T23:59:59Z"})
        for w in c["user"]["contributionsCollection"]["contributionCalendar"]["weeks"]:
            for day in w["contributionDays"]:
                days[day["date"]] = day["contributionCount"]
    langs = {}
    for r in d["repositories"]["nodes"]:
        for e in r["languages"]["edges"]:
            langs[e["node"]["name"]] = langs.get(e["node"]["name"], 0) + e["size"]
    return {
        "commits": d["contributionsCollection"]["totalCommitContributions"],
        "repos": d["repositories"]["totalCount"],
        "stars": sum(r["stargazerCount"] for r in d["repositories"]["nodes"]),
        "prs": d["pullRequests"]["totalCount"],
        "issues": d["issues"]["totalCount"],
        "langs": langs, "days": days,
    }

# ---------------- cards ----------------
def fmt(d): return f"{d.day:02d}/{d.month:02d}"

def card_geral(s):
    rows = [("COMMITS (12 MESES)", s["commits"]), ("REPOSITÓRIOS", s["repos"]), ("ESTRELAS", s["stars"]),
            ("PULL REQUESTS", s["prs"]), ("ISSUES", s["issues"])]
    b = head("GERAL")
    for i, (k, v) in enumerate(rows):
        y = 104 + i * 38
        b += f'<rect class="r" style="animation-delay:{i*.12:.2f}s" x="36" y="{y-26}" width="418" height="1" fill="#2a2a2a"/>'
        b += T(k, 36, y, 18, "r", "#bdbdbd", ls=1.5) + T(str(v), 454, y + 2, 26, "b", RED if i == 0 else LIGHT, "end")
    return svg(490, 290, b, ".r{transform-box:fill-box;transform-origin:left;animation:g .8s ease-out both}@keyframes g{from{transform:scaleX(0)}}")

def card_linguagens(s):
    tot = sum(s["langs"].values()) or 1
    top = sorted(s["langs"].items(), key=lambda kv: -kv[1])[:5]
    shades = [RED, "#f2f0ea", "#9a9a9a", "#5a5a5a", "#a3121a"]
    b = head("LINGUAGENS"); x = 36
    for i, (n, v) in enumerate(top):
        w = 418 * v / tot
        b += f'<rect class="bar" style="animation-delay:{i*.15:.2f}s" x="{x:.1f}" y="80" width="{max(w,2):.1f}" height="18" fill="{shades[i]}"/>'; x += w
    b = b.replace('y="80"', 'y="80"', 1)
    for i, (n, v) in enumerate(top):
        y = 140 + i * 30
        b += f'<rect x="36" y="{y-13}" width="13" height="13" rx="3" fill="{shades[i]}"/>' + T(n.upper(), 60, y, 18, "r", LIGHT, ls=1.2) + T(f"{100*v/tot:.1f}%", 454, y, 18, "r", "#bdbdbd", "end", 1)
    if not top: b += T("SEM DADOS AINDA", 36, 140, 18, "r", GREY, ls=1.2)
    return svg(490, 290, b, ".bar{transform-box:fill-box;transform-origin:left;animation:g .9s ease-out both}@keyframes g{from{transform:scaleX(0)}}")

def streaks(days):
    today = date.today(); ds = sorted(days)
    total = sum(days.values())
    first = date.fromisoformat(ds[0]) if ds else today
    best = cur = 0; best_end = best_start = run_start = None
    d = first
    while d <= today:
        if days.get(d.isoformat(), 0) > 0:
            if cur == 0: run_start = d
            cur += 1
            if cur > best: best, best_start, best_end = cur, run_start, d
        else:
            cur = 0
        d += timedelta(days=1)
    # sequência atual: hoje ainda sem commit não quebra
    c = 0; d = today
    if days.get(d.isoformat(), 0) == 0: d -= timedelta(days=1)
    end = d
    while days.get(d.isoformat(), 0) > 0: c += 1; d -= timedelta(days=1)
    return total, first, c, (d + timedelta(days=1), end), best, (best_start, best_end)

def card_sequencia(s):
    total, first, cur, (cs, ce), best, (bs, be) = streaks(s["days"])
    pct = 100 * cur / best if best else 0
    b = head("SEQUÊNCIA DE COMMITS")
    b += f'<path d="M333 80v150M667 80v150" stroke="#2a2a2a" stroke-width="2"/>'
    b += T(str(total), 166, 166, 58, "b", LIGHT, "middle") + T("CONTRIBUIÇÕES", 166, 200, 17, "r", "#bdbdbd", "middle", 2)
    b += T(f"DESDE {fmt(first)}/{first.year}", 166, 226, 15, "r", GREY, "middle", 1.5)
    b += f'<circle cx="500" cy="146" r="56" fill="none" stroke="#2a2a2a" stroke-width="8"/><circle class="ring" cx="500" cy="146" r="56" fill="none" stroke="{RED}" stroke-width="8" stroke-linecap="round" pathLength="100" stroke-dasharray="{pct:.1f} 100" transform="rotate(-90 500 146)"/>'
    b += T(str(cur), 500, 164, 50, "b", RED, "middle") + T("SEQUÊNCIA ATUAL", 500, 236, 17, "r", LIGHT, "middle", 2)
    if cur: b += T(f"{fmt(cs)} – {fmt(ce)}", 500, 260, 15, "r", GREY, "middle", 1.5)
    b += T(str(best), 834, 166, 58, "b", LIGHT, "middle") + T("MAIOR SEQUÊNCIA", 834, 200, 17, "r", "#bdbdbd", "middle", 2)
    if best: b += T(f"{fmt(bs)} – {fmt(be)}", 834, 226, 15, "r", GREY, "middle", 1.5)
    return svg(1000, 290, b, ".ring{animation:rg 1.4s ease-out both}@keyframes rg{from{stroke-dasharray:0 100}}")

def card_atividade(s):
    today = date.today(); n = 31
    pts = [(today - timedelta(days=n-1-i)) for i in range(n)]
    vals = [s["days"].get(d.isoformat(), 0) for d in pts]
    mx = max(vals + [1]); x0, x1, y0, y1 = 70, 960, 250, 90
    X = lambda i: x0 + (x1 - x0) * i / (n - 1); Y = lambda v: y0 - (y0 - y1) * v / mx
    b = head("ATIVIDADE · ÚLTIMOS 31 DIAS")
    for k in range(4):
        v = round(mx * k / 3); y = Y(v)
        b += f'<path d="M{x0} {y:.1f}H{x1}" stroke="#2a2a2a" stroke-width="1"/>' + T(str(v), x0 - 14, y + 6, 15, "r", GREY, "end")
    line = " ".join(f"{X(i):.1f},{Y(v):.1f}" for i, v in enumerate(vals))
    b += f'<polygon points="{x0},{y0} {line} {x1},{y0}" fill="{RED}" fill-opacity=".14"/>'
    b += f'<polyline class="ln" points="{line}" fill="none" stroke="{RED}" stroke-width="3" stroke-linejoin="round" pathLength="100" stroke-dasharray="100"/>'
    for i, v in enumerate(vals):
        if v: b += f'<circle cx="{X(i):.1f}" cy="{Y(v):.1f}" r="4.5" fill="{INK}" stroke="{RED}" stroke-width="2.5"/>'
        if i % 5 == 0 or i == n - 1: b += T(fmt(pts[i]), X(i), 282, 14, "r", GREY, "middle", 1)
    return svg(1000, 310, b, ".ln{animation:dr 2s ease-out both}@keyframes dr{from{stroke-dashoffset:100}}")

if __name__ == "__main__":
    data = json.load(open(sys.argv[1])) if len(sys.argv) > 1 else fetch()
    save("geral.svg", card_geral(data))
    save("linguagens.svg", card_linguagens(data))
    save("sequencia.svg", card_sequencia(data))
    save("atividade.svg", card_atividade(data))
    print("cards gerados em", OUT)
